 **10pts** (暴力做法,此代码为改进80pts代码的错误示范)

  思路:没有什么好说的，主要是把答案存储到队列中，再输出。

___Code___
  ```cpp
#include<iostream>
#include<queue>
using namespace std;
int main()
{
 int n,x;
 cin>>n;
 char a;
 queue <char> q,qq;
 while(cin>>a!=0) q.push(a);
 x=q.size();
 while(!q.empty())
 {
  x--;
  if(q.front()!='0') 
  {
   if(x!='0') qq.push('+');
   qq.push(q.front());
   qq.push('*');
   qq.push(n+'0');
   qq.push('^');
   qq.push(x+'0');
  }
  q.pop();
 }
    if(qq.front()=='+') qq.pop();
 while(!qq.empty())
 {
  cout<<qq.front();
  qq.pop();
  if(qq.front()=='+'&&qq.size()==1) return 0;
 }
 return 0;
}

50pts (出现一些奇怪的问题，例如少输出几个加号)

思路：同上，都是骗分的暴力做法

Code

#include<iostream>
#include<queue>
using namespace std;
int main()
{
  int n,x;
  cin>>n;
  char a;
  queue <char> q,qq;
  while(cin>>a!=0) q.push(a);
  x=q.size();
  while(!q.empty())
  {
   x--;
   if(q.front()!='0') cout<<q.front()<<'*'<<n<<'^'<<x;
   if(x!=0&&q.front()!=0&&qq.back()!='+') 
   {
    cout<<'+';
    qq.push('+');
   }
   q.pop();
  }
  return 0;
}

