100pts (加入了正确的特判)

思路：经过冥思苦想，我想到的一种方法。

首先用变量QAQ存储x进制数列的总值。
每次遇到非零的数，QAQ--，如果QAQ==0，说明后面全是零，不输出加号

Show my Code(拒绝抄袭,共建和谐洛谷)

#include<iostream>
#include<queue>
using namespace std;
int main()
{
 int n,x,qaq=0;
 cin>>n;
 char a;
 queue <char> q,qq;
 while(cin>>a!=0) 
 {
  q.push(a);
  qaq+=(a-'0');
 }
 x=q.size();
 while(!q.empty())
 {
  x--;
  if(q.front()!='0') 
  {
   qaq--;
   cout<<q.front()<<'*'<<n<<'^'<<x;
   if(x!=0&&qaq!=0) cout<<'+';
  }
  q.pop();
 }
 return 0;
}
